package com.mockarena.assessment.application;
import com.mockarena.assessment.domain.*; import com.mockarena.assessment.infrastructure.challenge.*; import com.mockarena.assessment.infrastructure.question.*; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class AttemptContentApplicationService { private final AttemptRepository attempts; private final AttemptItemRepository items; private final AttemptPersistenceService persistence; private final ChallengeVersionCatalogClient challenges; private final QuestionCandidateContentClient questions; private final Clock clock=Clock.systemUTC(); public AttemptContentApplicationService(AttemptRepository a,AttemptItemRepository i,AttemptPersistenceService p,ChallengeVersionCatalogClient c,QuestionCandidateContentClient q){attempts=a;items=i;persistence=p;challenges=c;questions=q;}
 public List<Item> content(UUID attemptId,UUID candidate){Attempt a=attempts.findById(attemptId).orElseThrow(()->new NoSuchElementException("Attempt not found"));if(!a.candidateUserId().equals(candidate))throw new SecurityException("Attempt is not owned by current user"); persistence.expireAndFindActive(candidate,a.assessmentVersionId(),clock.instant()); a=attempts.findById(attemptId).orElseThrow();if(a.status()!=AttemptStatus.IN_PROGRESS)throw new IllegalStateException("Attempt is not in progress");List<AttemptItem> route=items.findByAttemptIdOrderByGlobalPositionAsc(attemptId); List<UUID> challengeIds=route.stream().map(AttemptItem::challengeVersionId).distinct().toList(); challenges.resolveManifests(challengeIds); List<UUID> ids=route.stream().map(AttemptItem::questionVersionId).toList();Map<UUID,QuestionCandidateContent> content=new HashMap<>();questions.resolve(ids).forEach(q->content.put(q.questionVersionId(),q));return route.stream().map(i->{QuestionCandidateContent q=Optional.ofNullable(content.get(i.questionVersionId())).orElseThrow(ChallengeVersionNotComposableException::new);return new Item(i.globalPosition(),i.challengeId(),i.challengeVersionId(),i.questionId(),i.questionVersionId(),i.questionTypeCode(),q.title(),q.stem(),q.options(),q.constraints(),q.examples(),q.programmingLanguages());}).toList();}
 public record Item(int position,UUID challengeId,UUID challengeVersionId,UUID questionId,UUID questionVersionId,String questionTypeCode,String title,String stem,List<QuestionCandidateContent.Option> options,String constraints,com.fasterxml.jackson.databind.JsonNode examples,com.fasterxml.jackson.databind.JsonNode programmingLanguages){}
}
